css:
.print-heading { display: none !important; }

html, body {
  margin: 0 !important;
  padding: 0 !important;
  background: #fff !important;
}

@page { size: A4 portrait; margin: 2mm; }

.muster-card {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 11px;
  color: #000;
  background: #fff;
  box-sizing: border-box;
  width: 100%;
  height: auto;
  border: none;
  padding: 2mm 3mm;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.muster-layout {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  background: transparent;
}
.muster-layout > tbody > tr > td {
  vertical-align: top;
  padding: 1mm;
  border: none;
  background: transparent;
}
.col-left { width: 50%; }
.col-right {
  width: 50%;
  padding-right: 4mm !important;
  overflow: hidden;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  height: auto;
}

.wage-frame {
  display: block;
  width: 100%;
  box-sizing: border-box;
  border: 1.5px solid #000;
  border-radius: 12px;
  overflow: hidden;
  background: transparent;
}
.wage-grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  background: transparent;
  border: none;
}
.wage-grid > tbody > tr:first-child > td {
  border-top: none;
}
.wage-grid > tbody > tr > td:first-child {
  border-left: none;
}
.wage-grid > tbody > tr > td:last-child {
  border-right: none;
}
.wage-grid > tbody > tr:last-child > td {
  border-bottom: none;
}
.wage-grid .leave-wrap {
  padding: 0 !important;
  border-right: none !important;
  border-bottom: none !important;
}
.wage-grid col.c1 { width: 22%; }
.wage-grid col.c2 { width: 22%; }
.wage-grid col.c3 { width: 6%; }
.wage-grid col.c4 { width: 25%; }
.wage-grid col.c5 { width: 25%; }

.wage-grid > tbody > tr > td {
  border: 1px solid #000;
  padding: 1px 3px;
  height: 8mm;
  font-size: 9.5px;
  line-height: 1.1;
  vertical-align: middle;
  background: transparent;
  color: #000;
  box-sizing: border-box;
}

.wage-grid .lbl {
  font-weight: 400;
  text-align: left;
  white-space: normal;
}
.wage-grid .box {
  text-align: right;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  font-size: 11px;
  padding-left: 1px;
  padding-right: 2px;
  vertical-align: middle;
}
.wage-grid .date-val { text-align: left; font-size: 10px; }
.wage-grid .empty { padding: 0; }

/* leave fills exactly 4 outer rows — no overflow, no taller Date */
.wage-grid .leave-wrap {
  padding: 0 !important;
  vertical-align: top !important;
  height: 32mm; /* 4 x 8mm */
  max-height: 32mm;
  overflow: hidden;
}

.leave-inner {
  width: 100%;
  height: 32mm;
  max-height: 32mm;
  border-collapse: collapse;
  table-layout: fixed;
  background: transparent;
}
.leave-inner col.ll { width: 50%; }
.leave-inner col.lb { width: 50%; }

.leave-inner td {
  border: none;
  border-bottom: 1px solid #000;
  border-right: none;
  padding: 0 2px;
  height: 6.4mm; /* 32/5 */
  max-height: 6.4mm;
  color: #000;
  font-size: 9px;
  line-height: 1.05;
  vertical-align: middle;
  background: transparent;
  overflow: hidden;
}
.leave-inner tr:last-child td { border-bottom: none; }
.leave-inner .box { border-right: none !important; }
.leave-inner .lbl {
  font-weight: 400;
  text-align: left;
  border-right: 1px solid #000;
}
.leave-inner .box {
  width: 50%;
  border-right: none !important;
  text-align: right;
  font-weight: 700;
  font-size: 11px;
  overflow: hidden;
  vertical-align: middle;
}
.wage-grid td.leave-vert {
  width: 6% !important;
  max-width: 22px !important;
  text-align: center;
  padding: 0 !important;
  vertical-align: middle !important;
  overflow: hidden;
}
.wage-grid td.leave-vert .leave-txt {
  display: inline-block;
  font-family: inherit;
  font-weight: 400;
  font-size: 8px;
  letter-spacing: 0;
  line-height: 1;
  white-space: nowrap;
  writing-mode: vertical-rl;
  -webkit-writing-mode: vertical-rl;
  transform: rotate(180deg);
  -webkit-transform: rotate(180deg);
}

.right-head {
  text-align: center;
  width: 100%;
  box-sizing: border-box;
  margin: 0px 0 10mm 0;
  padding: 15mm 0 0 0;
  line-height: 1;
  position: relative;
}
.right-head .brand {
  position: absolute;
  top: 0;
  left: 0;
  width: auto;
  text-align: left;
  line-height: 1;
  font-weight: 500;
  font-size: 15px;
  letter-spacing: 0.2px;
}
.right-head .brand sup {
  font-size: 5px;
  top: -7px;
}
.right-head .brand span {
  display: block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  padding-left: 20px;
}
.right-head .rule, .right-head .rule-no {
  font-size: 15px;
  font-weight: 400;
  line-height: 1.3;
}
.right-head .title {
  display: block;
  font-size: 21px;
  font-weight: 600;
  margin-top: 0.2mm;
  line-height: 1.05;
  white-space: nowrap;
}
.right-head .sub {
  font-size: 13px;
  font-weight: 500;
  margin-top: 0;
  line-height: 1.5;
}

.form-lines { width: 100%; }
.fline {
  display: flex;
  align-items: flex-end;
  min-height: 6mm;
  margin-bottom: 1.8mm;
}
.fline .fl {
  flex: 0 0 auto;
  white-space: nowrap;
  font-weight: 400;
  font-size: 12px;
  padding-right: 4px;
  padding-bottom: 1px;
}
.fline .fl.stack {
  white-space: normal;
  line-height: 1.05;
  padding-bottom: 1px;
}
.fline .fv {
  flex: 1 1 auto;
  border-bottom: 1px solid #000;
  font-weight: 700;
  font-size: 12px;
  min-height: 4mm;
  padding: 0 3px 1px;
}
.fline.split .fv.short,
.fline.age-row .fv.short {
  flex: 0 1 18%;
  min-width: 16mm;
  max-width: 28mm;
}
.fline.split .fv.mid { flex: 1 1 28%; min-width: 18mm; }
.fline .gap { padding-left: 6mm; }
.fline.age-row .fv:first-child {
  flex: 1 1 auto;
}
.fline.age-row {
  justify-content: flex-start;
}
.fline.address-line .fv {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}
.fline .fl.ghost {
  visibility: hidden;
}

@media print {
  @page { size: A4 portrait; margin: 2mm; }
  html, body {
    background: #fff !important;
    width: 100% !important;
    height: auto !important;
    min-height: 0 !important;
    overflow: visible !important;
  }
  html, body, .print-format {
    background: #fff !important;
    width: 100% !important;
  }
  .print-format {
    margin: 0 0 0 76px;
    width: 90% !important;
    max-width: 202mm !important;
    min-height: 0 !important;
    height: auto !important;
    padding: 0 !important;
    overflow: visible !important;
  }
  .muster-card,
  .muster-layout,
  .col-right {
    height: auto !important;
    min-height: 0 !important;
    page-break-inside: auto !important;
    page-break-after: auto !important;
    page-break-before: auto !important;
  }
  .muster-card {
    width: 100% !important;
    min-height: 0 !important;
    background: #fff !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    page-break-inside: auto;
  }
  .wage-frame {
    border: 1.5px solid #000 !important;
    border-radius: 12px !important;
    overflow: hidden !important;
  }
}

@media screen {
  .print-format {
    background: #fff !important;
    padding: 4mm !important;
    margin: 0 0 0 76px;
    width: 90% !important;
    max-width: 210mm !important;
    min-height: 0 !important;
    height: auto !important;
    box-sizing: border-box;
    overflow: visible !important;
  }
  .muster-card {
    min-height: 0 !important;
    height: auto !important;
    background: #fff !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
}

.print-block * {
  box-sizing: border-box;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.print-block {
  width: 100%;
  max-width: 100%;
  margin: 0;
  background: #fff;
  padding: 12px 5mm 0;
  display: block;
  box-sizing: border-box;
  font-family: Calibri, Arial, sans-serif;
  color: #111;
}
.print-block .card {
  width: 100%;
  max-width: 100%;
  background: #fff;
  border: 1px solid #222;
  border-radius: 18px;
  overflow: hidden;
}
.print-block table {
  width: 100% !important;
  max-width: 100% !important;
  margin: 0;
  table-layout: fixed !important;
  border-collapse: collapse !important;
  border-spacing: 0 !important;
  background: #fff;
  font-size: 9px;
  border: 0;
}
.print-block th,
.print-block td {
  border: 1px solid #222 !important;
  padding: 4px 3px !important;
  text-align: center !important;
  vertical-align: middle !important;
  color: #111 !important;
  -webkit-text-fill-color: #111 !important;
}
.print-block tr.cols th:first-child,
.print-block tbody td:first-child { border-left: 0 !important; }
.print-block tr.cols th:last-child,
.print-block tbody td:last-child { border-right: 0 !important; }
.print-block tbody tr:last-child td { border-bottom: 0 !important; }
.print-block th {
  font-size: 8px;
  font-weight: 700;
  text-transform: capitalize;
  line-height: 1.15;
  background: #fff;
}
.print-block tr.cols th {
  height: 116px;
  border-top: 0 !important;
}
.print-block tr.cols th,
.print-block tr.cols th b,
.print-block tr.cols th span {
  font-weight: bold;
  font-size: 10px;
}
.print-block th.col-date {
  width: 6mm !important;
  text-transform: capitalize;
  white-space: nowrap;
  color: #111 !important;
  writing-mode: horizontal-tb !important;
}
.print-block th.col-date b { color: #111 !important; }
.print-block th.col-vert {
  width: 8mm !important;
  padding: 4px 2px !important;
  writing-mode: vertical-rl !important;
  writing-mode: sideways-lr !important;
  transform: none !important;
  white-space: nowrap;
  color: #111 !important;
  -webkit-text-fill-color: #111 !important;
  -webkit-font-smoothing: antialiased !important;
}
.print-block th.col-ot { width: 5mm !important; }
.print-block td { height: 24px; padding-top: 2px !important; padding-bottom: 2px !important; }
.print-block td.day { font-size: 11px; font-weight: 400; color: #111 !important; }
.print-block td.total { font-weight: 700; font-size: 11px; }
.print-block .time { font-weight: 700; font-size: 11px; }
.print-block td.status { font-weight: 400; font-size: 11px; }
.print-block .sign-row {
  width: 100%;
  max-width: 100%;
  margin: 40px 0 0;
  text-align: right;
  white-space: nowrap;
}
.print-block .sign-label {
  font-size: 13px;
  font-weight: 700;
  color: #111 !important;
  -webkit-text-fill-color: #111 !important;
  line-height: 1.2;
}
.print-block .sign-line {
  display: inline-block;
  width: 42mm;
  margin-left: 8px;
  border: 0;
  border-bottom: 1px solid #111 !important;
  vertical-align: baseline;
  height: 0.7em;
}
@media print {
  .print-block th,
  .print-block td,
  .print-block th.col-vert,
  .print-block th.col-date,
  .print-block .sign-label {
    color: #111 !important;
    -webkit-text-fill-color: #111 !important;
  }
  .print-block th.col-vert {
    writing-mode: vertical-rl !important;
    writing-mode: sideways-lr !important;
  }
  .print-block th.col-date {
    writing-mode: horizontal-tb !important;
  }
  .print-block,
  .print-block .card { page-break-inside: avoid; }
}

html:
{%- set doc = frappe.get_doc(doc.doctype, doc.name) -%}

{%- set company_address = frappe.db.get_value("Company", doc.company, "address") if doc.company else "" -%}

{%- set cl = frappe.db.get_value(
    "Company Link",
    doc.employee,
    ["employee", "date_of_joining", "designation", "department", "category", "skill_type"],
    as_dict=1
) if doc.employee else {} -%}

{%- set emp_link = cl.employee if cl else None -%}
{%- set doj = cl.date_of_joining if cl else None -%}
{%- set designation = cl.designation if cl else (doc.designation or "") -%}
{%- set category = cl.category if cl else (doc.category or "") -%}
{%- set skill_type = cl.skill_type if cl else (doc.skill_type or "") -%}
{%- set nature_of_work = skill_type or category or "" -%}

{%- set emp = frappe.db.get_value(
    "Employee",
    emp_link,
    ["gender", "date_of_birth"],
    as_dict=1
) if emp_link else {} -%}

{%- set gender = emp.gender if emp else "" -%}
{%- set dob = emp.date_of_birth if emp else None -%}
{%- if dob -%}
  {%- set age_years = frappe.utils.date_diff(frappe.utils.today(), dob) // 365 -%}
{%- else -%}
  {%- set age_years = None -%}
{%- endif -%}

{%- set shift_row = frappe.db.sql("""
    SELECT st.start_time, st.end_time
    FROM `tabShift Assignment` sa
    INNER JOIN `tabShift Type` st ON st.name = sa.shift
    WHERE sa.employee = %s
      AND sa.status = 'Active'
      AND sa.from_date <= %s
      AND (sa.to_date IS NULL OR sa.to_date = '' OR sa.to_date >= %s)
    ORDER BY sa.from_date DESC
    LIMIT 1
""", (doc.employee, doc.end_date, doc.start_date), as_dict=1) -%}

{%- set work_from = "" -%}
{%- set work_to = "" -%}
{%- if shift_row -%}
  {%- set work_from = frappe.utils.format_time(shift_row[0].start_time) if shift_row[0].start_time else "" -%}
  {%- set work_to = frappe.utils.format_time(shift_row[0].end_time) if shift_row[0].end_time else "" -%}
{%- endif -%}

{%- set ssa = frappe.db.sql("""
    SELECT name
    FROM `tabSalary Structure Assignment`
    WHERE employee = %s
      AND docstatus = 1
      AND from_date <= %s
      AND (to_date IS NULL OR to_date >= %s)
    ORDER BY from_date DESC
    LIMIT 1
""", (doc.employee, doc.end_date, doc.start_date), as_dict=1) -%}

{%- set wage_rate = namespace(v=0) -%}
{%- if ssa -%}
  {%- set rate_rows = frappe.db.sql("""
      SELECT amount, per_day_rate, daily_wage_component, salary_component
      FROM `tabSalary Details`
      WHERE parent = %s
        AND parenttype = 'Salary Structure Assignment'
        AND parentfield = 'earnings'
        AND amount > 0
      ORDER BY idx ASC
  """, (ssa[0].name,), as_dict=1) -%}
  {%- for r in rate_rows -%}
    {%- set cname = (r.salary_component or "")|lower -%}
    {%- if "basic" in cname or cname == "da" or cname.startswith("da ") or "dearness" in cname -%}
      {%- if r.daily_wage_component and r.per_day_rate -%}
        {%- set wage_rate.v = wage_rate.v + (r.per_day_rate or 0) -%}
      {%- else -%}
        {%- set wage_rate.v = wage_rate.v + (r.amount or 0) -%}
      {%- endif -%}
    {%- endif -%}
  {%- endfor -%}
  {%- if wage_rate.v == 0 -%}
    {%- for r in rate_rows -%}
      {%- if r.daily_wage_component and r.per_day_rate -%}
        {%- set wage_rate.v = wage_rate.v + (r.per_day_rate or 0) -%}
      {%- else -%}
        {%- set wage_rate.v = wage_rate.v + (r.amount or 0) -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endif -%}

{%- set ot = namespace(v=0) -%}
{%- set normal = namespace(v=0) -%}
{%- for e in doc.earnings -%}
  {%- set amt = e.amount or 0 -%}
  {%- if amt > 0 -%}
    {%- set cname = (e.salary_component or "")|lower -%}
    {%- if "overtime" in cname or cname == "ot" or cname.startswith("ot ") or cname.endswith(" ot") or " ot " in cname -%}
      {%- set ot.v = ot.v + amt -%}
    {%- else -%}
      {%- set normal.v = normal.v + amt -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

{%- set advance = namespace(v=0) -%}
{%- set other_ded = namespace(v=0) -%}
{%- set emp_ded_total = namespace(v=0) -%}
{%- for d in doc.deductions -%}
  {%- set is_er = frappe.db.get_value("Salary Component", d.salary_component, "employer_contribution") -%}
  {%- set amt = d.amount or 0 -%}
  {%- if amt > 0 and not is_er -%}
    {%- set emp_ded_total.v = emp_ded_total.v + amt -%}
    {%- set cname = (d.salary_component or "")|lower -%}
    {%- if cname.startswith("advance") or "advance" in cname -%}
      {%- set advance.v = advance.v + amt -%}
    {%- else -%}
      {%- set other_ded.v = other_ded.v + amt -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

{%- set gross = doc.total_earnings or (normal.v + ot.v) -%}
{%- set nett = doc.net_salary or ((gross or 0) - emp_ded_total.v) -%}
{%- set days_worked = doc.payment_days if doc.payment_days is not none else (doc.present_days or 0) -%}
{%- set leave_enjoyed = doc.total_earned_leaves or 0 -%}

{%- macro fmt(val) -%}
{{- "{:,.2f}".format(frappe.utils.flt(val or 0, 2)) -}}
{%- endmacro -%}

<div class="muster-card">
  <table class="muster-layout">
    <tr>
      <td class="col-right">
        <div class="right-head">
          <div class="brand">Saral<sup>&reg;</sup><span>HR</span></div>
          <div class="title">Muster Cum Wages Slip</div>
          <div class="sub">(Attendance Card)</div>
        </div>
        <div class="form-lines">
          <div class="fline">
            <span class="fl stack">Name of the<br>Establishment :</span>
            <span class="fv">{{ doc.company or "" }}</span>
          </div>
          {%- set addr = (company_address or "")|string|trim -%}
          {%- set addr_line1 = addr -%}
          {%- set addr_line2 = "" -%}
          {%- if addr|length > 36 -%}
            {%- set split_at = addr[:50].rfind(", ") -%}
            {%- if split_at < 20 -%}
              {%- set split_at = addr[:50].rfind(" ") -%}
            {%- endif -%}
            {%- if split_at >= 20 -%}
              {%- set addr_line1 = addr[:split_at]|trim -%}
              {%- set addr_line2 = addr[split_at + 1:]|trim -%}
            {%- else -%}
              {%- set addr_line1 = addr[:50]|trim -%}
              {%- set addr_line2 = addr[50:]|trim -%}
            {%- endif -%}
          {%- endif -%}
          <div class="fline address-line">
            <span class="fl">Address :</span>
            <span class="fv">{{ addr_line1 }}</span>
          </div>
          <div class="fline address-line">
            <span class="fl ghost">Address :</span>
            <span class="fv">{{ addr_line2 }}</span>
          </div>
          <div class="fline">
            <span class="fl stack">Name of the<br>Employee :</span>
            <span class="fv">{{ doc.employee_name or "" }}</span>
          </div>
          <div class="fline">
            <span class="fl stack">Name of the<br>Employer :</span>
            <span class="fv">{{ doc.company or "" }}</span>
          </div>
          <div class="fline age-row">
            <span class="fv"></span>
            <span class="fl">Age</span>
            <span class="fv short">{{ age_years if age_years is not none else "" }}</span>
            <span class="fl gap">Sex</span>
            <span class="fv short">{{ gender or "" }}</span>
          </div>
          <div class="fline split">
            <span class="fl">Nature of work</span><span class="fv mid">{{ nature_of_work }}</span>
            <span class="fl gap">Designation</span><span class="fv mid">{{ designation or "" }}</span>
          </div>
          <div class="fline split">
            <span class="fl">Working Hours from</span><span class="fv mid">{{ work_from }}</span>
            <span class="fl gap">to</span><span class="fv mid">{{ work_to }}</span>
          </div>
          <div class="fline split">
            <span class="fl">Interval for Rest from</span><span class="fv mid"></span>
            <span class="fl gap">to</span><span class="fv mid"></span>
          </div>
          <div class="fline">
            <span class="fl">For the month of</span>
            <span class="fv">{{ frappe.utils.formatdate(doc.start_date, "MMMM yyyy") if doc.start_date else "" }}</span>
          </div>
        </div>
      </td>
      <td class="col-left">
        <div class="wage-frame"><table class="wage-grid">
          <colgroup>
            <col class="c1">
            <col class="c2">
            <col class="c3">
            <col class="c4">
            <col class="c5">
          </colgroup>
          <tr>
            <td class="lbl">Total Days<br>Worked</td>
            <td class="box">{{ days_worked }}</td>
            <td class="lbl r-lbl" colspan="2">Advance</td>
            <td class="box">{% if advance.v %}{{ fmt(advance.v) }}{% endif %}</td>
          </tr>
          <tr>
            <td class="lbl">Actual Rates Of<br>Wages</td>
            <td class="box">{% if wage_rate.v %}{{ fmt(wage_rate.v) }}{% endif %}</td>
            <td class="lbl r-lbl" colspan="2">Other<br>deductions</td>
            <td class="box">{% if other_ded.v %}{{ fmt(other_ded.v) }}{% endif %}</td>
          </tr>
          <tr>
            <td class="lbl">Total Piece<br>Rate Production</td>
            <td class="box"></td>
