{%- set rec = doc.get_attendance_record_print_context() -%}
{%- macro vert_label(text) -%}{{ text }}{%- endmacro %}
<div class="print-block">
	<div class="card">
		<table border="1">
			<thead>
				<tr class="cols">
					<th class="col-date"><b>Date</b></th>
					<th class="col-vert">{{ vert_label("In time") }}</th>
					<th class="col-vert">{{ vert_label("Out time") }}</th>
					<th class="col-vert col-ot">{{ vert_label("Overtime") }}</th>
					<th class="col-vert">{{ vert_label("total hours") }}</th>
					<th class="col-date"><b>Date</b></th>
					<th class="col-vert">{{ vert_label("In time") }}</th>
					<th class="col-vert">{{ vert_label("Out time") }}</th>
					<th class="col-vert col-ot">{{ vert_label("Overtime") }}</th>
					<th class="col-vert">{{ vert_label("total hours") }}</th>
				</tr>
			</thead>
			<tbody>
				{% for row in rec.pairs %}
				<tr>
					<td class="day">{{ row.left.day | e }}</td>
					{% if row.left.status %}
					<td class="status">{{ row.left.status | e }}</td>
					<td class="status">{{ row.left.status | e }}</td>
					{% else %}
					<td class="time">{{ row.left.in_time | e }}</td>
					<td class="time">{{ row.left.out_time | e }}</td>
					{% endif %}
					<td class="time">{{ row.left.overtime | e }}</td>
					<td class="time">{{ row.left.total_hours | e }}</td>
					<td{% if row.right.day == "TOTAL" %} class="total"{% else %} class="day"{% endif %}>{{ row.right.day | e }}</td>
					{% if row.right.status %}
					<td class="status">{{ row.right.status | e }}</td>
					<td class="status">{{ row.right.status | e }}</td>
					{% else %}
					<td class="time">{{ row.right.in_time | e }}</td>
					<td class="time">{{ row.right.out_time | e }}</td>
					{% endif %}
					<td class="{% if row.right.day == "TOTAL" %}total{% else %}time{% endif %}">{{ row.right.overtime | e }}</td>
					<td class="{% if row.right.day == "TOTAL" %}total{% else %}time{% endif %}">{{ row.right.total_hours | e }}</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>
	</div>
	<div class="sign-row">
		<span class="sign-label">Signature</span><span class="sign-line"></span>
	</div>
</div>
